  {
   "rule_id": "R-HNSAL-S2-R01-01",
   "status": "OK",
   "label": "가입 대상 명의 유형",
   "source": {
    "quote": "실명의개인또는개인사업자(1인1계좌)"
   },
   "condition": {
    "in": [
     {
      "var": "customer.holder_type"
     },
     [
      "INDIVIDUAL",
      "SOLE_PROPRIETOR"
     ]
    ]
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  },
  {
   "rule_id": "R-HNSAL-S2-R01-02",
   "status": "OK",
   "label": "중복 가입 금지",
   "source": {
    "quote": "※”연금하나월복리적금“ 또는\"주거래 하나월복리적금\"과중복가입이불가합니다."
   },
   "condition": {
    "exists": {
     "event": "ACCOUNT_OPENING",
     "within": {
      "ref": "$window"
     }
    }
   },
   "effect": {
    "type": "DISQUALIFY"
   }
  }
 ]
}

