raw_first:
{
 "rules": [
  {
   "rule_id": "R-HNSAL-S2-R09-01",
   "status": "OK",
   "label": "급여하나우대",
   "source": {
    "quote": "급여하나우대 이예금만기전전월말기준, 계약기간의1/2 이상본인명의하나은행입출금통장을 (연0.90%) 통해급여입금실적(주1) 보유한경우(월1회이체)"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      ">=": [
       {
        "count_distinct_months": {
         "event": "SALARY_TRANSFER",
         "within": {
          "ref": "$window"
         }
        }
       },
       1
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "EARLY"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.9,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-HNSAL-S2-R09-02",
   "status": "OK",
   "label": "온라인채널가입 우대",
   "source": {
    "quote": "온라인채널가입 이예금을온라인채널(스마트폰뱅킹/인터넷뱅킹)을통해가입또는만기재예치하는 또는 경우(단, 만기재예치우대는최초계약기간이후재예치된기간에대해적용)"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "contract.channel"
       },
       [
        "ONLINE",
        "INTERNET"
       ]
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "EARLY"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-HNSAL-S2-R09-03",
   "status": "OK",
   "label": "재예치우대",
   "source": {
    "quote": "재예치우대 예시) ’21.3월1년제가입(재예치신청)계좌: ’22.3월재예치후만기해지시재예치우 대금리적용"
   },
   "let": {
    "window": {
     "month_range": {
      "from": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "first"
      },
      "to": {
       "anchor": "contract.reference_date",
       "offset_months": -1,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "contract.channel"
       },
       [
        "ONLINE",
        "INTERNET"
       ]
      ]
     },
     {
      "not": {
       "in": [
        {
         "var": "contract.termination_type"
        },
        [
         "EARLY"
        ]
       ]
      }
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.1,
    "unit": "PERCENT"
   }
  }
 ]
