{
 "rules": [
  {
   "rule_id": "R-HNWSH-S2-R10-01",
   "status": "OK",
   "label": "목표 불입금액 달성 우대금리",
   "source": {
    "quote": "① 목표 불입금액 달성 우대 (연 0.2%)"
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "contract.termination_type"
       },
       [
        "MATURITY"
       ]
      ]
     },
     {
      ">=": [
       {
        "var": "contract.amount"
       },
       {
        "count_events": {
         "event": "DEPOSIT",
         "within": {
          "ref": "$contract_term"
         }
        }
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": 0.2,
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-HNWSH-S2-R10-02",
   "status": "OK",
   "label": "소비 재테크 자동 적립 우대금리",
   "source": {
    "quote": "② 소비 재테크 자동 적립 우대 (최대 연 0.4%)"
   },
   "let": {
    "contract_term": {
     "month_range": {
      "from": {
       "anchor": "contract.start_date",
       "offset_months": 0,
       "day": "first"
      },
      "to": {
       "anchor": "contract.maturity_date",
       "offset_months": 0,
       "day": "last"
      }
     }
    }
   },
   "condition": {
    "and": [
     {
      "in": [
       {
        "var": "contract.termination_type"
       },
       [
        "MATURITY"
       ]
      ]
     },
     {
      ">=": [
       {
        "var": "count_events"
       },
       {
        "event": "CARD_USAGE",
        "within": {
         "ref": "$contract_term"
        }
       }
      ]
     }
    ]
   },
   "effect": {
    "type": "RATE_ADD",
    "value": {
      "switch": {
        "case": {
          ">=": [
            {
              "var": "count_events"
            },
            10
          ],
          "value": 0.1
        },
        "case": {
          ">=": [
            {
              "var": "count_events"
            },
            20
          ],
          "value": 0.2
        },
        "case": {
          ">=": [
            {
              "var": "count_events"
            },
            30
          ],
          "value": 0.3
        },
        "case": {
          ">=": [
            {
              "var": "count_events"
            },
            40
          ],
          "value": 0.4
        },
        "default": 0
      }
    },
    "unit": "PERCENT"
   }
  },
  {
   "rule_id": "R-HNWSH-S2-R10-03",
   "status": "OK",
   "label": "추천인 우대금리",
